        save()
    }

    func updateHabit(id: UUID, name: String?, type: String?, frequency: String?, streak: Int?, completed: Bool?, notes: String?) {
        habits = habits.map { habit in
            if habit.id == id {
                return WellnessHabit(
                    name: name ?? habit.name,
                    type: type ?? habit.type,
                    frequency: frequency ?? habit.frequency,
                    streak: streak ?? habit.streak,
                    completed: completed ?? habit.completed,
                    notes: notes ?? habit.notes
                )
            } else {
                return habit
            }
        }
        save()
    }

    func removeHabit(id: UUID) {
        habits = habits.filter { $0.id != id }
        save()
    }
}
